// Test viewport scrolls when at bottom
TEST_F(EditorCmdNewlineTest, ViewportScrollsWhenAtBottom) {
    // Create enough lines to require scrolling
    SetBuffer("L0\nL1\nL2\nL3\nL4\nL5\nL6\nL7\nL8\nL9\nL10\n"
              "L11\nL12\nL13\nL14\nL15\nL16\nL17\nL18\nL19\nL20\n"
              "L21\nL22");

    // Position at end of "L21" (last visible line but one, cy = 21)
    char *last_line = editor_start_of_line_n(self, 21);
    SetPos(last_line - self->buf + strlen("L21"));
    ASSERT_EQ(21, self->cy);
    ASSERT_EQ(0, self->py);

    MmResult result = editor_cmd_newline(self);

    EXPECT_EQ(kOk, result);
    EXPECT_CURSOR_EQ(0, 21); // cy stays one before bottom
    EXPECT_VIEWPORT_EQ(0, 1); // Viewport scrolled
    EXPECT_EQ(24, self->num_lines);
}

