// Test page down updates txtp correctly
TEST_F(EditorCmdPageDownTest, UpdatesTxtpCorrectly) {
    std::string content;
    for (int i = 0; i < 50; i++) {
        content += "ABCD\n";
    }
    SetBuffer(content.c_str());

    self->py = 5;
    self->cy = 3;
    self->cx = 2;
    self->txtp = editor_start_of_line_n(self, self->py + self->cy) + self->cx;

    MmResult result = editor_cmd_page_down(self);

    EXPECT_EQ(kOk, result);
    // After page down, should be at line (8 + height) = 31, column 2
    char *expected = self->buf;
    for (int i = 0; i < 8 + self->height; i++) {
        while (*expected != '\n') expected++;
        expected++;
    }
    expected += 2;
    EXPECT_EQ(expected, self->txtp);
}

