// Test selection symmetry (forward and backward produce same bounds)
TEST_F(EditorGetSelectionTest, SelectionSymmetry) {
    SetBuffer("Hello World\n");

    // Forward selection
    self->mark = self->buf + 2;
    SetPos(8);

    char *fwd_start = nullptr;
    char *fwd_end = nullptr;
    size_t fwd_length = editor_get_selection(self, &fwd_start, &fwd_end);

    // Backward selection with swapped positions
    self->mark = self->buf + 8;
    SetPos(2);

    char *bwd_start = nullptr;
    char *bwd_end = nullptr;
    size_t bwd_length = editor_get_selection(self, &bwd_start, &bwd_end);

    // Should produce identical results
    EXPECT_EQ(fwd_length, bwd_length);
    EXPECT_EQ(fwd_start, bwd_start);
    EXPECT_EQ(fwd_end, bwd_end);
}

// Test that pointers are within buffer bounds
TEST_F(EditorGetSelectionTest, PointersWithinBufferBounds) {
    SetBuffer("Test String\n");
    self->mark = self->buf + 0;
    SetPos(11);

    char *start = nullptr;
    char *end = nullptr;
    size_t length = editor_get_selection(self, &start, &end);

    EXPECT_GE(start, self->buf);
    EXPECT_LT(start, self->buf + self->buf_sz);
    EXPECT_GE(end, self->buf);
    EXPECT_LT(end, self->buf + self->buf_sz);
    EXPECT_EQ(11, length);
}

// Test selection doesn't include character at txtp (forward)
TEST_F(EditorGetSelectionTest, DoesNotIncludeCharacterAtTxtp) {
    SetBuffer("0123456789\n");
    self->mark = self->buf + 0;  // At '0'
    SetPos(5);                   // At '5'

    char *start = nullptr;
    char *end = nullptr;
    size_t length = editor_get_selection(self, &start, &end);

    EXPECT_EQ(5, length);
    std::string selected(start, length);
    EXPECT_EQ("01234", selected);
    EXPECT_EQ('5', *self->txtp);
}

// Test selection doesn't include character at mark (backward)
TEST_F(EditorGetSelectionTest, DoesNotIncludeCharacterAtMark) {
    SetBuffer("0123456789\n");
    self->mark = self->buf + 5;  // At '5'
    SetPos(0);                   // At '0'

    char *start = nullptr;
    char *end = nullptr;
    size_t length = editor_get_selection(self, &start, &end);

    EXPECT_EQ(5, length);
    std::string selected(start, length);
    EXPECT_EQ("01234", selected);
    EXPECT_EQ('5', *self->mark);
}

// Test zero-length selection at different positions
TEST_F(EditorGetSelectionTest, ZeroLengthAtVariousPositions) {
    SetBuffer("Hello\n");

    // At start
    self->mark = self->buf + 0;
    SetPos(0);
    char *s1, *e1;
    EXPECT_EQ(0, editor_get_selection(self, &s1, &e1));

    // In middle
    self->mark = self->buf + 2;
    SetPos(2);
    char *s2, *e2;
    EXPECT_EQ(0, editor_get_selection(self, &s2, &e2));

    // At end
    self->mark = self->buf + 6;
    SetPos(6);
    char *s3, *e3;
    EXPECT_EQ(0, editor_get_selection(self, &s3, &e3));
}

