    ASSERT_EQ(kOk, editor_set_changed_lines(self, 3, 4));
    ASSERT_EQ(kOk, editor_set_changed_lines(self, 2, 3)); // Extend backward
    ASSERT_EQ(kOk, editor_set_changed_lines(self, 4, 5)); // Extend forward
